import { EXIT_CODES, NotFoundError, TodoError, UsageError } from './errors.js';
import { displayText, formatTodoList } from './format.js';
import { loadTodos, resolveTodosPath, updateTodos } from './store.js';
import { addTodo, completeTodo, deleteTodo, normalizeText, parseId } from './todos.js';

/** How the CLI refers to itself in help text and hints. */
export const CLI_NAME = 'node index.js';

const HELP_FLAGS = new Set(['--help', '-h']);
const END_OF_OPTIONS = '--';

const COMMANDS = Object.freeze({
  add: { args: '<text>', description: 'Add a new todo', run: runAdd },
  list: { args: '', description: 'List all todos with their status', run: runList },
  complete: { args: '<id>', description: 'Mark a todo as done', run: runComplete },
  delete: { args: '<id>', description: 'Delete a todo', run: runDelete },
  help: { args: '', description: 'Show this help', run: runHelp },
});

/**
 * @typedef {object} RunOptions
 * @property {string} [cwd] directory whose todos.json is used
 * @property {{ write(chunk: string): unknown }} [stdout]
 * @property {{ write(chunk: string): unknown }} [stderr]
 * @property {() => Date} [now] clock used for createdAt
 * @property {import('./store.js').LockOptions} [lock]
 */

/**
 * Runs one CLI command. Expected failures are printed to stderr; this never
 * throws for them.
 * @param {string[]} argv arguments after `node index.js`
 * @param {RunOptions} [options]
 * @returns {Promise<number>} process exit code, see EXIT_CODES
 */
export async function run(argv, options = {}) {
  const { cwd = process.cwd(), stdout = process.stdout, stderr = process.stderr, now = () => new Date(), lock } = options;
  const [name, ...args] = argv;

  if (name === undefined) {
    stderr.write(`${usage()}\n`);
    return EXIT_CODES.USAGE;
  }

  try {
    const command = resolveCommand(name, args);
    await command.run({ args, filePath: resolveTodosPath(cwd), stdout, now, lock });
    return EXIT_CODES.SUCCESS;
  } catch (error) {
    return reportError(error, stderr);
  }
}

/** @returns {string} the help text, without a trailing newline */
function usage() {
  const rows = Object.entries(COMMANDS).map(([name, { args, description }]) => ({
    synopsis: `${name} ${args}`.trimEnd(),
    description,
  }));
  const width = rows.reduce((max, row) => Math.max(max, row.synopsis.length), 0) + 4;
  const commandLines = rows.map(({ synopsis, description }) => `  ${synopsis.padEnd(width)}${description}`);
  return [
    `Usage: ${CLI_NAME} <command> [arguments]`,
    '',
    'Commands:',
    ...commandLines,
    '',
    'Todos are stored in todos.json in the current directory.',
  ].join('\n');
}

function resolveCommand(name, args) {
  if (HELP_FLAGS.has(name)) {
    return COMMANDS.help;
  }
  // Object.hasOwn keeps inherited names such as "constructor" from resolving to a command.
  if (!Object.hasOwn(COMMANDS, name)) {
    throw new UsageError(`Unknown command "${name}".`);
  }
  // `add --help` and `complete -h` show help rather than adding a todo named "--help".
  if (args.length === 1 && HELP_FLAGS.has(args[0])) {
    return COMMANDS.help;
  }
  return COMMANDS[name];
}

async function runAdd({ args, filePath, stdout, now, lock }) {
  const words = args[0] === END_OF_OPTIONS ? args.slice(1) : args;
  if (words.length === 0) {
    throw new UsageError(`Missing todo text. Usage: ${CLI_NAME} add "<text>"`);
  }
  // Validate before taking the lock so bad input never waits on, or touches, the file.
  const text = normalizeText(words.join(' '));
  const { todo } = await updateTodos(filePath, (state) => addTodo(state, text, { now: now() }), lock);
  stdout.write(`Added todo #${todo.id}: ${displayText(todo.text)}\n`);
}

async function runList({ args, filePath, stdout }) {
  if (args.length > 0) {
    throw new UsageError(`"list" takes no arguments, got: ${args.join(' ')}`);
  }
  const { todos } = await loadTodos(filePath);
  if (todos.length === 0) {
    stdout.write(`No todos yet. Add one with: ${CLI_NAME} add "<text>"\n`);
    return;
  }
  stdout.write(`${formatTodoList(todos)}\n`);
}

async function runComplete({ args, filePath, stdout, lock }) {
  const id = parseIdArgument('complete', args);
  const { todo, changed } = await updateTodos(filePath, (state) => completeTodo(state, id), lock);
  const status = changed ? `Completed todo #${id}` : `Todo #${id} is already completed`;
  stdout.write(`${status}: ${displayText(todo.text)}\n`);
}

async function runDelete({ args, filePath, stdout, lock }) {
  const id = parseIdArgument('delete', args);
  const { todo } = await updateTodos(filePath, (state) => deleteTodo(state, id), lock);
  stdout.write(`Deleted todo #${id}: ${displayText(todo.text)}\n`);
}

async function runHelp({ stdout }) {
  stdout.write(`${usage()}\n`);
}

function parseIdArgument(command, args) {
  if (args.length === 0) {
    throw new UsageError(`Missing todo id. Usage: ${CLI_NAME} ${command} <id>`);
  }
  if (args.length > 1) {
    throw new UsageError(`"${command}" takes exactly one id, got ${args.length}: ${args.join(' ')}`);
  }
  return parseId(args[0]);
}

function reportError(error, stderr) {
  if (!(error instanceof TodoError)) {
    stderr.write(`Unexpected error: ${error?.stack ?? String(error)}\n`);
    return EXIT_CODES.FAILURE;
  }
  stderr.write(`Error: ${error.message}\n`);
  if (error instanceof UsageError) {
    stderr.write(`Run "${CLI_NAME} help" for usage.\n`);
  } else if (error instanceof NotFoundError) {
    stderr.write(`Run "${CLI_NAME} list" to see existing ids.\n`);
  }
  return error.exitCode;
}
/** Process exit codes used by the CLI. */
export const EXIT_CODES = Object.freeze({
  SUCCESS: 0,
  FAILURE: 1,
  USAGE: 2,
});

/**
 * Base class for expected failures. The CLI prints these as a one-line
 * message instead of a stack trace and exits with `exitCode`.
 */
export class TodoError extends Error {
  /**
   * @param {string} message
   * @param {{ exitCode?: number, cause?: unknown }} [options]
   */
  constructor(message, { exitCode = EXIT_CODES.FAILURE, cause } = {}) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = new.target.name;
    this.exitCode = exitCode;
  }
}

/** The command line was malformed: unknown command, missing or invalid argument. */
export class UsageError extends TodoError {
  /** @param {string} message */
  constructor(message) {
    super(message, { exitCode: EXIT_CODES.USAGE });
  }
}

/** No todo has the requested id. */
export class NotFoundError extends TodoError {
  /** @param {number} id */
  constructor(id) {
    super(`No todo with id ${id}.`);
    this.id = id;
  }
}

/** todos.json could not be read, parsed, validated, locked, or written. */
export class StorageError extends TodoError {
  /**
   * @param {string} message
   * @param {{ cause?: unknown }} [options]
   */
  constructor(message, { cause } = {}) {
    super(message, { cause });
  }
}
/** @typedef {import('./todos.js').Todo} Todo */

/** Status markers shown by the `list` command. */
export const STATUS_MARKERS = Object.freeze({ done: '[x]', pending: '[ ]' });

const CONTROL_CHARACTERS = /\p{Cc}/gu;

/**
 * `add` rejects control characters, but a hand-edited todos.json may still
 * contain them. Escaping them as `\uXXXX` keeps each todo on one line and
 * stops stored text from sending escape sequences to the terminal.
 * @param {string} text
 * @returns {string}
 */
export function displayText(text) {
  return text.replace(CONTROL_CHARACTERS, (char) => `\\u${char.codePointAt(0).toString(16).padStart(4, '0')}`);
}

/**
 * @param {Todo} todo
 * @param {number} [idWidth] pad the id to this many characters so markers line up
 * @returns {string} e.g. " 7. [x] Buy groceries"
 */
export function formatTodo(todo, idWidth = 0) {
  const marker = todo.completed ? STATUS_MARKERS.done : STATUS_MARKERS.pending;
  return `${String(todo.id).padStart(idWidth)}. ${marker} ${displayText(todo.text)}`;
}

/**
 * One line per todo in id order, then a blank line and a done/pending summary.
 * @param {readonly Todo[]} todos not modified
 * @returns {string} without a trailing newline
 */
export function formatTodoList(todos) {
  const sorted = todos.toSorted((a, b) => a.id - b.id);
  // reduce rather than Math.max(...ids): spreading a very large array overflows the call stack.
  const idWidth = sorted.reduce((width, todo) => Math.max(width, String(todo.id).length), 0);
  const doneCount = sorted.filter((todo) => todo.completed).length;
  const noun = sorted.length === 1 ? 'todo' : 'todos';
  const summary = `${sorted.length} ${noun}: ${doneCount} done, ${sorted.length - doneCount} pending`;
  return [...sorted.map((todo) => formatTodo(todo, idWidth)), '', summary].join('\n');
}
import { NotFoundError, TodoError, UsageError } from './errors.js';

/**
 * @typedef {object} Todo
 * @property {number} id
 * @property {string} text
 * @property {boolean} completed
 * @property {string} createdAt ISO 8601 timestamp
 */

/**
 * @typedef {object} TodoState
 * @property {number} nextId id the next added todo receives; never reused after delete
 * @property {Todo[]} todos
 */

/**
 * Every operation returns this shape. `changed` is false when the state was
 * left as-is, so the caller can skip rewriting the file.
 * @typedef {object} TodoResult
 * @property {TodoState} state
 * @property {Todo} todo the todo that was added, completed, or deleted
 * @property {boolean} changed
 */

/** Maximum todo text length, counted in Unicode code points rather than UTF-16 units. */
export const MAX_TEXT_LENGTH = 500;

const ID_PATTERN = /^\d+$/;
// A newline or tab inside the text would break the one-line-per-todo list output.
const CONTROL_CHARACTER = /\p{Cc}/u;

/** @returns {TodoState} */
export function createEmptyState() {
  return { nextId: 1, todos: [] };
}

/**
 * Trims the text and applies Unicode NFC, so the same visible text is always
 * stored as the same code points.
 * @param {unknown} text
 * @param {{ maxLength?: number }} [options]
 * @returns {string}
 * @throws {UsageError} when the text is not a string, blank, too long, or contains control characters
 */
export function normalizeText(text, { maxLength = MAX_TEXT_LENGTH } = {}) {
  if (typeof text !== 'string') {
    throw new UsageError(`Todo text must be a string, got ${typeof text}.`);
  }
  const normalized = text.normalize('NFC').trim();
  if (normalized === '') {
    throw new UsageError('Todo text cannot be empty.');
  }
  if (CONTROL_CHARACTER.test(normalized)) {
    throw new UsageError('Todo text cannot contain control characters such as newlines or tabs.');
  }
  const length = [...normalized].length;
  if (length > maxLength) {
    throw new UsageError(`Todo text is too long: ${length} characters (maximum ${maxLength}).`);
  }
  return normalized;
}

/**
 * Parses a todo id typed by the user. Only plain decimal digits are accepted,
 * so "1.5", "-1", "1e3" and "0x10" are rejected instead of being coerced.
 * @param {unknown} raw
 * @returns {number}
 * @throws {UsageError}
 */
export function parseId(raw) {
  if (typeof raw !== 'string') {
    throw new UsageError(`Todo id must be a string of digits, got ${typeof raw}.`);
  }
  const trimmed = raw.trim();
  const id = Number(trimmed);
  if (!ID_PATTERN.test(trimmed) || !Number.isSafeInteger(id) || id < 1) {
    throw new UsageError(`Invalid id "${raw}": expected a positive whole number such as 1.`);
  }
  return id;
}

/**
 * @param {TodoState} state not modified
 * @param {string} text
 * @param {{ now?: Date, maxLength?: number }} [options]
 * @returns {TodoResult}
 */
export function addTodo(state, text, { now = new Date(), maxLength } = {}) {
  if (!Number.isSafeInteger(state.nextId)) {
    throw new TodoError(`Cannot assign an id: next id ${state.nextId} exceeds the largest safe integer.`);
  }
  const todo = {
    id: state.nextId,
    text: normalizeText(text, { maxLength }),
    completed: false,
    createdAt: now.toISOString(),
  };
  return {
    state: { nextId: state.nextId + 1, todos: [...state.todos, todo] },
    todo,
    changed: true,
  };
}

/**
 * Completing a todo that is already done is not an error; it returns the
 * input state with `changed: false`.
 * @param {TodoState} state not modified
 * @param {number} id
 * @returns {TodoResult}
 * @throws {NotFoundError}
 */
export function completeTodo(state, id) {
  const index = indexOfId(state, id);
  const existing = state.todos[index];
  if (existing.completed) {
    return { state, todo: existing, changed: false };
  }
  const todo = { ...existing, completed: true };
  return { state: { ...state, todos: state.todos.with(index, todo) }, todo, changed: true };
}

/**
 * `nextId` is left unchanged, so a deleted todo's id is never handed out again.
 * @param {TodoState} state not modified
 * @param {number} id
 * @returns {TodoResult}
 * @throws {NotFoundError}
 */
export function deleteTodo(state, id) {
  const index = indexOfId(state, id);
  return {
    state: { ...state, todos: state.todos.toSpliced(index, 1) },
    todo: state.todos[index],
    changed: true,
  };
}

function indexOfId(state, id) {
  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new NotFoundError(id);
  }
  return index;
}
import { randomBytes } from 'node:crypto';
import { open, readFile, rename, rm, stat } from 'node:fs/promises';
import path from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';
import { StorageError } from './errors.js';
import { parseState } from './schema.js';
import { createEmptyState } from './todos.js';

/** @typedef {import('./todos.js').TodoState} TodoState */
/** @typedef {import('./todos.js').TodoResult} TodoResult */

/**
 * @typedef {object} LockOptions
 * @property {number} [timeoutMs] give up waiting for another process after this long
 * @property {number} [retryMs] wait between attempts to take the lock
 * @property {number} [staleMs] a lock older than this is treated as abandoned
 */

/** Name of the data file, resolved against the working directory. */
export const TODOS_FILENAME = 'todos.json';

/** Lock settings used when the caller does not override them. */
export const DEFAULT_LOCK_OPTIONS = Object.freeze({ timeoutMs: 5000, retryMs: 25, staleMs: 30_000 });

/** Upper bound on a single read or write of todos.json, so a hung filesystem cannot block forever. */
export const IO_TIMEOUT_MS = 10_000;

const LOCK_HELD = 'held';
const LOCK_RELEASED = 'released';
const LOCK_STALE = 'stale';

/**
 * @param {string} cwd
 * @returns {string} absolute path of todos.json inside `cwd`
 */
export function resolveTodosPath(cwd) {
  return path.resolve(cwd, TODOS_FILENAME);
}

/**
 * A missing or empty file is an empty list. Invalid content raises an error
 * rather than being replaced, so a typo in a hand-edited file never costs data.
 * @param {string} filePath
 * @returns {Promise<TodoState>}
 * @throws {StorageError}
 */
export async function loadTodos(filePath) {
  let contents;
  try {
    contents = await readFile(filePath, { encoding: 'utf8', signal: AbortSignal.timeout(IO_TIMEOUT_MS) });
  } catch (error) {
    if (error.code === 'ENOENT') {
      return createEmptyState();
    }
    throw new StorageError(`Could not read ${filePath}: ${error.message}`, { cause: error });
  }

  // Some Windows editors prepend a byte order mark, which JSON.parse rejects.
  const json = contents.replace(/^\uFEFF/, '');
  if (json.trim() === '') {
    return createEmptyState();
  }
  let data;
  try {
    data = JSON.parse(json);
  } catch (error) {
    throw new StorageError(
      `${filePath} is not valid JSON (${error.message}). The file was left unchanged; fix or remove it.`,
      { cause: error },
    );
  }
  return parseState(data, filePath);
}

/**
 * Writes to a temporary file in the same directory, flushes it, then renames
 * it over todos.json. Readers see either the old file or the new one, never
 * a partial write.
 * @param {string} filePath
 * @param {TodoState} state
 * @returns {Promise<void>}
 * @throws {StorageError}
 */
export async function saveTodos(filePath, state) {
  const tempPath = `${filePath}.${process.pid}.${randomBytes(6).toString('hex')}.tmp`;
  const json = `${JSON.stringify({ nextId: state.nextId, todos: state.todos }, null, 2)}\n`;
  try {
    const handle = await open(tempPath, 'wx');
    try {
      await handle.writeFile(json, { encoding: 'utf8', signal: AbortSignal.timeout(IO_TIMEOUT_MS) });
      await handle.sync();
    } finally {
      await handle.close();
    }
    await rename(tempPath, filePath);
  } catch (error) {
    try {
      await rm(tempPath, { force: true });
    } catch (cleanupError) {
      throw new StorageError(
        `Could not write ${filePath}: ${error.message} (removing ${tempPath} also failed: ${cleanupError.message})`,
        { cause: error },
      );
    }
    throw new StorageError(`Could not write ${filePath}: ${error.message}`, { cause: error });
  }
}

/**
 * Runs `fn` while holding `<filePath>.lock`, so concurrent CLI invocations
 * cannot interleave their read-modify-write cycles and lose updates. A lock
 * whose owner process has exited, or that is older than `staleMs`, is taken over.
 * @template T
 * @param {string} filePath
 * @param {() => Promise<T>} fn
 * @param {LockOptions} [options]
 * @returns {Promise<T>}
 * @throws {StorageError} when the lock cannot be taken within `timeoutMs`
 */
export async function withFileLock(filePath, fn, options = {}) {
  const settings = { ...DEFAULT_LOCK_OPTIONS, ...options };
  const lockPath = `${filePath}.lock`;
  const handle = await acquireLock(lockPath, settings);
  try {
    try {
      await handle.writeFile(`${process.pid}\n`, 'utf8');
    } finally {
      await handle.close();
    }
    return await fn();
  } finally {
    await rm(lockPath, { force: true });
  }
}

/**
 * Loads the todos, applies `mutate`, and saves the result if `changed` is
 * true, all under the file lock.
 * @param {string} filePath
 * @param {(state: TodoState) => TodoResult} mutate
 * @param {LockOptions} [lockOptions]
 * @returns {Promise<TodoResult>}
 */
export async function updateTodos(filePath, mutate, lockOptions) {
  return withFileLock(
    filePath,
    async () => {
      const result = mutate(await loadTodos(filePath));
      if (result.changed) {
        await saveTodos(filePath, result.state);
      }
      return result;
    },
    lockOptions,
  );
}

async function acquireLock(lockPath, { timeoutMs, retryMs, staleMs }) {
  const deadline = Date.now() + timeoutMs;
  // Sequential by design: each attempt runs only after the previous one found the lock taken.
  for (;;) {
    try {
      return await open(lockPath, 'wx');
    } catch (error) {
      if (error.code !== 'EEXIST') {
        throw new StorageError(`Could not create lock file ${lockPath}: ${error.message}`, { cause: error });
      }
    }

    const lockState = await inspectLock(lockPath, staleMs);
    if (lockState === LOCK_STALE) {
      await rm(lockPath, { force: true });
    }
    if (lockState !== LOCK_HELD) {
      continue;
    }
    if (Date.now() >= deadline) {
      throw new StorageError(
        `Timed out after ${timeoutMs} ms waiting for ${lockPath}. ` +
          'If no other todo command is running, delete that file and try again.',
      );
    }
    await delay(retryMs);
  }
}

async function inspectLock(lockPath, staleMs) {
  let info;
  let contents;
  try {
    info = await stat(lockPath);
    contents = await readFile(lockPath, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') {
      return LOCK_RELEASED;
