/** Runs `node index.js ...args` as a child process in `cwd`. */
export function runCli(args, { cwd }) {
  return new Promise((resolve, reject) => {
    execFile(
      process.execPath,
      [INDEX_PATH, ...args],
      { cwd, timeout: CLI_TIMEOUT_MS, encoding: 'utf8' },
      (error, stdout, stderr) => {
        // A numeric code means the CLI ran and exited non-zero; anything else is a spawn failure or timeout.
        if (error && typeof error.code !== 'number') {
          reject(new Error(`node index.js ${args.join(' ')} did not exit normally: ${error.message}`, { cause: error }));
          return;
        }
        resolve({ code: error ? error.code : 0, stdout, stderr });
      },
    );
  });
}

/** Runs the CLI in this process with captured output, for tests that need custom options. */
export async function runInProcess(args, { cwd, ...options }) {
  const stdout = createCapture();
  const stderr = createCapture();
  const code = await run(args, { cwd, stdout, stderr, ...options });
  return { code, stdout: stdout.text(), stderr: stderr.text() };
}

function createCapture() {
  const chunks = [];
  return {
    write(chunk) {
      chunks.push(String(chunk));
      return true;
    },
    text: () => chunks.join(''),
  };
}

