  if (typeof text !== 'string') {
    throw new UsageError(`Todo text must be a string, got ${typeof text}.`);
  }
  const normalized = text.normalize('NFC').trim();
  if (normalized === '') {
    throw new UsageError('Todo text cannot be empty.');
  }
  if (CONTROL_CHARACTER.test(normalized)) {
    throw new UsageError('Todo text cannot contain control characters such as newlines or tabs.');
  }
  const length = [...normalized].length;
  if (length > maxLength) {
    throw new UsageError(`Todo text is too long: ${length} characters (maximum ${maxLength}).`);
  }
  return normalized;
}

/**
 * Parses a todo id typed by the user. Only plain decimal digits are accepted,
 * so "1.5", "-1", "1e3" and "0x10" are rejected instead of being coerced.
 * @param {unknown} raw
 * @returns {number}
 * @throws {UsageError}
 */
export function parseId(raw) {
  if (typeof raw !== 'string') {
    throw new UsageError(`Todo id must be a string of digits, got ${typeof raw}.`);
  }
  const trimmed = raw.trim();
  const id = Number(trimmed);
  if (!ID_PATTERN.test(trimmed) || !Number.isSafeInteger(id) || id < 1) {
    throw new UsageError(`Invalid id "${raw}": expected a positive whole number such as 1.`);
  }
  return id;
}

/**
 * @param {TodoState} state not modified
 * @param {string} text
 * @param {{ now?: Date, maxLength?: number }} [options]
 * @returns {TodoResult}
 */
export function addTodo(state, text, { now = new Date(), maxLength } = {}) {
  if (!Number.isSafeInteger(state.nextId)) {
    throw new TodoError(`Cannot assign an id: next id ${state.nextId} exceeds the largest safe integer.`);
  }
  const todo = {
    id: state.nextId,
    text: normalizeText(text, { maxLength }),
    completed: false,
    createdAt: now.toISOString(),
  };
  return {
    state: { nextId: state.nextId + 1, todos: [...state.todos, todo] },
    todo,
    changed: true,
  };
}

/**
 * Completing a todo that is already done is not an error; it returns the
 * input state with `changed: false`.
 * @param {TodoState} state not modified
 * @param {number} id
 * @returns {TodoResult}
 * @throws {NotFoundError}
 */
export function completeTodo(state, id) {
  const index = indexOfId(state, id);
  const existing = state.todos[index];
  if (existing.completed) {
    return { state, todo: existing, changed: false };
  }
  const todo = { ...existing, completed: true };
  return { state: { ...state, todos: state.todos.with(index, todo) }, todo, changed: true };
}

/**
 * `nextId` is left unchanged, so a deleted todo's id is never handed out again.
 * @param {TodoState} state not modified
 * @param {number} id
 * @returns {TodoResult}
 * @throws {NotFoundError}
 */
export function deleteTodo(state, id) {
  const index = indexOfId(state, id);
  return {
    state: { ...state, todos: state.todos.toSpliced(index, 1) },
    todo: state.todos[index],
    changed: true,
  };
}

function indexOfId(state, id) {
  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new NotFoundError(id);
  }
  return index;
}

