    assert.equal((await readTodosFile(dir)).todos[0].text, '--help');
  });

  it('succeeds without rewriting when the text is unchanged', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'One');
    const before = await readTodosFile(dir);
    const result = await runCli(['edit', '1', 'One'], { cwd: dir });
    assert.equal(result.code, 0);
    assert.equal(result.stdout, 'Todo #1 already has this text: One\\n');
    await assertUnchanged(dir, before);
  });

  it('exits 2 without an id', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'One');
    const before = await readTodosFile(dir);
    const result = await runCli(['edit'], { cwd: dir });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /Error: Missing todo id\\./);
    await assertUnchanged(dir, before);
  });

  it('exits 2 without text', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'One');
    const before = await readTodosFile(dir);
    const result = await runCli(['edit', '1'], { cwd: dir });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /Error: Missing todo text\\./);
    assert.match(result.stderr, /Run "node index\\.js help" for usage\\./);
    await assertUnchanged(dir, before);
  });

  for (const [label, args] of [['an empty string', ['1', '']], ['whitespace', ['1', '   ']], ['only --', ['1', '--']]]) {
    it(`exits 2 for ${label} as text`, async (t) => {
      const dir = await makeTempDir(t);
      await seed(dir, 'One');
      const before = await readTodosFile(dir);
      const result = await runCli(['edit', ...args], { cwd: dir });
      assert.equal(result.code, 2);
      assert.match(result.stderr, /^Error: /);
      await assertUnchanged(dir, before);
    });
  }

  it('exits 2 for an invalid id', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'One');
    const before = await readTodosFile(dir);
    const result = await runCli(['edit', 'abc', 'New'], { cwd: dir });
    assert.equal(result.code, 2);
    assert.match(result.stderr, /Invalid id "abc"/);
    await assertUnchanged(dir, before);
  });

  it('exits 1 and suggests "list" when the id does not exist', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'One');
    const before = await readTodosFile(dir);
    const result = await runCli(['edit', '99', 'New'], { cwd: dir });
    assert.equal(result.code, 1);
    assert.equal(result.stderr, 'Error: No todo with id 99.\\nRun "node index.js list" to see existing ids.\\n');
    await assertUnchanged(dir, before);
  });

  it('does not create todos.json when there are no todos', async (t) => {
    const dir = await makeTempDir(t);
    const result = await runCli(['edit', '1', 'New'], { cwd: dir });
    assert.equal(result.code, 1);
    await assertNoTodosFile(dir);
  });

  it('rejects text containing a control character', async (t) => {
    const dir = await makeTempDir(t);
    await seed(dir, 'One');
    const before = await readTodosFile(dir);
    const result = await runCli(['edit', '1', 'a\\tb'], { cwd: dir });
    assert.equal(result.code, 2);
    await assertUnchanged(dir, before);
  });

  it('shows help for "edit --help"', async (t) => {
    const result = await runCli(['edit', '--help'], { cwd: await makeTempDir(t) });
    assert.equal(result.code, 0);
    assert.match(result.stdout, /^Usage:/);
  });
